use vstd::prelude::*;
use vstd::vec::*;

verus! {

fn all_prefixes(s: Vec<char>) -> (result: Vec<Vec<char>>)
    requires
        s.len() <= usize::MAX, // Ensure length is within bounds
    ensures
        // Result length equals input length
        result.len() == s.len(),
        // Each element in result is a prefix of s
        forall|i: int| 0 <= i < result.len() ==> 
            result[i].len() == i + 1,
        // All prefixes are valid prefixes of the original string
        forall|i: int| 0 <= i < result.len() ==>
            forall|j: int| 0 <= j <= i ==> 
                result[i][j] == s[j],
        // The prefixes are in increasing length order
        forall|i: int, j: int| 0 <= i < j < result.len() ==>
            result[i].len() < result[j].len(),
        // The last prefix equals the original string
        result.len() > 0 ==> result[result.len() - 1] == s
{
    let mut result = Vec::new();
    let mut current_prefix = Vec::new();
    
    let mut index = 0;
    while index < s.len()
        invariant
            0 <= index <= s.len(),
            result.len() == index,
            current_prefix.len() == index,
            forall|i: int| 0 <= i < index ==> 
                result[i].len() == i + 1,
            forall|i: int| 0 <= i < index ==>
                forall|j: int| 0 <= j <= i ==> 
                    result[i][j] == s[j],
            forall|i: int| 0 <= i < index ==>
                current_prefix[i] == s[i],
            forall|i: int, j: int| 0 <= i < j < index ==>
                result[i].len() < result[j].len(),
    {
        let ch = s[index];
        current_prefix.push(ch);
        result.push(current_prefix.clone());
        
        index = index + 1;
    }
    
    result
}

} // verus!